const fs = require("fs");
const path = require("path");
const cp = require("child_process");
const dir = "/w/temporalmock";
fs.rmSync(dir, { recursive: true, force: true });
fs.mkdirSync(dir, { recursive: true });
// Node 24 has no native Temporal, so install a minimal stand-in (Now and Instant only).
fs.writeFileSync(path.join(dir, "temporal-stub.mjs"), [
  "if (typeof globalThis.Temporal === 'undefined') {",
  "  const realNow = Date.now.bind(Date)",
  "  class Instant {",
  "    constructor(ns) { this.epochNanoseconds = ns }",
  "    get epochMilliseconds() { return Number(this.epochNanoseconds / 1000000n) }",
  "    static fromEpochNanoseconds(ns) { return new Instant(ns) }",
  "  }",
  "  globalThis.Temporal = {",
  "    Instant,",
  "    Now: {",
  "      instant() { return Instant.fromEpochNanoseconds(BigInt(realNow()) * 1000000n) },",
  "      timeZoneId() { return 'UTC' },",
  "    },",
  "  }",
  "}",
].join("\n") + "\n");
fs.writeFileSync(path.join(dir, "now.test.mjs"), [
  "import './temporal-stub.mjs'",
  "import { test, vi } from 'vitest'",
  "import { writeFileSync } from 'node:fs'",
  "test('setSystemTime without fake timers', () => {",
  "  const fakeBefore = vi.isFakeTimers()",
  "  vi.setSystemTime(0)",
  "  const dateMs = Date.now()",
  "  const temporalMs = Temporal.Now.instant().epochMilliseconds",
  "  vi.useRealTimers()",
  "  writeFileSync(new URL('./result.json', import.meta.url), JSON.stringify({ fakeBefore, dateMs, temporalMs }))",
  "})",
].join("\n") + "\n");
const r = cp.spawnSync(process.execPath, ["/w/node_modules/vitest/vitest.mjs", "run"], {
  cwd: dir,
  encoding: "utf8",
  env: { ...process.env, NO_COLOR: "1", CI: "1", NODE_OPTIONS: "--import=file://" + dir + "/temporal-stub.mjs" },
  timeout: 60000,
});
console.log((r.stdout || "") + (r.stderr || "") + (r.error ? String(r.error) : ""));
const resultFile = path.join(dir, "result.json");
if (!fs.existsSync(resultFile)) {
  console.error("ERROR: the test file wrote no result (exit " + r.status + ")");
  process.exit(2);
}
const res = JSON.parse(fs.readFileSync(resultFile, "utf8"));
console.log(JSON.stringify(res));
if (res.fakeBefore !== false || res.dateMs !== 0) {
  console.error("ERROR: unexpected setup (fake timers " + res.fakeBefore + ", Date.now() " + res.dateMs + ")");
  process.exit(2);
}
if (res.temporalMs === 0) {
  console.log("PASS: vi.setSystemTime(0) without fake timers mocked Temporal.Now.instant()");
  process.exit(0);
}
if (typeof res.temporalMs === "number" && res.temporalMs > 1e12) {
  console.error("FAIL: Temporal.Now.instant() returned the real time after vi.setSystemTime(0) without fake timers");
  process.exit(1);
}
console.error("ERROR: unexpected Temporal.Now.instant().epochMilliseconds " + res.temporalMs);
process.exit(2);

